/*
 * Research renderer; NOT a replacement for the actual DOM backdrop compositor.
 * Inspired by shadercn's persistent WebGPU pipeline + uniform updates.
 * The same authored source texture is shared with the browser CSS reference.
 * The signed-distance-derived RGBA maps are generated by the unmodified
 * Oracle JS and provided as data textures. No arbitrary DOM capture occurs.
 */
import {generateOracleField,sidebarFiniteBlurProjection,
  ORACLE_FINITE_REFRACTION} from "/app/assets/sidebar-glass-oracle.js";

const blurShader=`
struct Parameters { dimensions: vec2f, direction: vec2f, sigma: f32, _pad: f32, _pad2: vec2f };
@group(0) @binding(0) var source: texture_2d<f32>;
@group(0) @binding(1) var sampleLinear: sampler;
@group(0) @binding(2) var<uniform> params: Parameters;
@vertex fn vert(@builtin(vertex_index) vertexIndex:u32)->@builtin(position) vec4f {
  var p=array<vec2f,3>(vec2f(-1.,-1.),vec2f(3.,-1.),vec2f(-1.,3.));
  return vec4f(p[vertexIndex],0.,1.);
}
@fragment fn frag(@builtin(position) coord:vec4f)->@location(0) vec4f {
  let uv=coord.xy / params.dimensions;
  let sigma=max(params.sigma,0.0001);
  let cutoff=3.*sigma;
  var total=vec4f(0.);
  var sum=0.;
  for(var i:i32=-24; i<=24; i=i+1){
    let p=f32(i);
    if(abs(p)>cutoff){continue;}
    let weight=exp(-0.5*p*p/(sigma*sigma));
    total+=textureSampleLevel(source,sampleLinear,uv+params.direction*p/params.dimensions,0.)*weight;
    sum+=weight;
  }
  return total / max(sum,0.00001);
}
`;

const glassShader=`
struct Parameters { dimensions: vec2f, _padding: vec2f };
@group(0) @binding(0) var nearTexture: texture_2d<f32>;
@group(0) @binding(1) var farTexture: texture_2d<f32>;
@group(0) @binding(2) var innerMap: texture_2d<f32>;
@group(0) @binding(3) var outerMap: texture_2d<f32>;
@group(0) @binding(4) var blurMask: texture_2d<f32>;
@group(0) @binding(5) var texSampler: sampler;
@group(0) @binding(6) var<uniform> params: Parameters;
@vertex fn vert(@builtin(vertex_index) vertexIndex:u32)->@builtin(position) vec4f {
  var p=array<vec2f,3>(vec2f(-1.,-1.),vec2f(3.,-1.),vec2f(-1.,3.));
  return vec4f(p[vertexIndex],0.,1.);
}
fn blurredAt(uv:vec2f,channel:u32)->vec4f {
  // The SVG reference composites near + far coverage using 'in', 'out',
  // then 'over'. These premultiplied alpha equations mirror that graph.
  let mask=textureSampleLevel(blurMask,texSampler,uv,0.);
  let nearWeight=select(mask.r,mask.g,channel==1u);
  let n=textureSampleLevel(nearTexture,texSampler,uv,0.);
  let f=textureSampleLevel(farTexture,texSampler,uv,0.);
  let nearPart=n*nearWeight;
  let farPart=f*(1.-nearWeight);
  return nearPart + farPart*(1.-nearPart.a);
}
@fragment fn frag(@builtin(position) coord:vec4f)->@location(0) vec4f {
  let uv=coord.xy/params.dimensions;
  let innerField=textureSampleLevel(innerMap,texSampler,uv,0.);
  let outerField=textureSampleLevel(outerMap,texSampler,uv,0.);
  // Identical SVG displacement scale 128, including 8-bit map quantization.
  let innerUv=uv + (innerField.rg-vec2f(0.5))*128./params.dimensions;
  let outerUv=uv + (outerField.rg-vec2f(0.5))*128./params.dimensions;
  let inner=blurredAt(innerUv,0u);
  let outer=blurredAt(outerUv,1u);
  let a=innerField.b;
  let outerPart=outer*a;
  let innerPart=inner*(1.-a);
  let combined=outerPart + innerPart*(1.-outerPart.a);
  // Source public output color path is unproved: identity passthrough.
  // Transparent pane tint is applied by the CSS layer above the canvas.
  return combined;
}
`;

async function pipeline(device,code,format){
  const module=device.createShaderModule({code});
  const compilation=await module.getCompilationInfo();
  const errors=compilation.messages.filter(m=>m.type==="error");
  if(errors.length)throw Error("WGSL compilation: "+errors.map(m=>m.message).join(" | "));
  return device.createRenderPipeline({
    layout:"auto",
    vertex:{module,entryPoint:"vert"},
    fragment:{module,entryPoint:"frag",targets:[{format}]},
    primitive:{topology:"triangle-list"}
  });
}

export async function createGPUExperiment(canvas,input,width,height,radius=24){
  if(!navigator.gpu)throw Error("WebGPU is unavailable in this browser");
  const adapter=await navigator.gpu.requestAdapter();
  if(!adapter)throw Error("No WebGPU adapter available");
  const device=await adapter.requestDevice();
  const context=canvas.getContext("webgpu");
  if(!context)throw Error("Cannot initialize WebGPU canvas");
  const outputFormat=navigator.gpu.getPreferredCanvasFormat();
  canvas.width=width;canvas.height=height;
  context.configure({device,format:outputFormat,alphaMode:"premultiplied"});
  const nearFarFormat="rgba8unorm";
  const usage=GPUTextureUsage.TEXTURE_BINDING|GPUTextureUsage.RENDER_ATTACHMENT|GPUTextureUsage.COPY_DST;
  const tex=()=>device.createTexture({size:[width,height],format:nearFarFormat,usage});
  const src=tex(),tmpNear=tex(),tmpFar=tex(),near=tex(),far=tex();
  const inner=tex(),outer=tex(),blur=tex();
  const textures=[src,tmpNear,tmpFar,near,far,inner,outer,blur];
  const write=(target,data)=>device.queue.writeTexture(
    {texture:target},data,{bytesPerRow:width*4,rowsPerImage:height},[width,height]);
  write(src,input);
  const field=generateOracleField(width,height,radius);
  write(inner,field.inner);write(outer,field.outer);write(blur,field.blurMask);
  const sampler=device.createSampler({magFilter:"linear",minFilter:"linear",addressModeU:"clamp-to-edge",addressModeV:"clamp-to-edge"});
  const blurPipeline=await pipeline(device,blurShader,nearFarFormat);
  const compositePipeline=await pipeline(device,glassShader,outputFormat);
  const nearSigma=sidebarFiniteBlurProjection("regular",width,height).word /
    ORACLE_FINITE_REFRACTION.surfaceScale/2;
  const farSigma=nearSigma*2;
  const configs=[
    {from:src,to:tmpNear,sigma:nearSigma,direction:[1,0]},
    {from:tmpNear,to:near,sigma:nearSigma,direction:[0,1]},
    {from:src,to:tmpFar,sigma:farSigma,direction:[1,0]},
    {from:tmpFar,to:far,sigma:farSigma,direction:[0,1]}
  ];
  const stageInputs=configs.map(c=>{
    const buffer=device.createBuffer({size:32,usage:GPUBufferUsage.UNIFORM|GPUBufferUsage.COPY_DST});
    device.queue.writeBuffer(buffer,0,new Float32Array([width,height,...c.direction,c.sigma,0,0,0]));
    const group=device.createBindGroup({layout:blurPipeline.getBindGroupLayout(0),entries:[
      {binding:0,resource:c.from.createView()},{binding:1,resource:sampler},
      {binding:2,resource:{buffer}}
    ]});
    return {...c,buffer,group};
  });
  const finalParams=device.createBuffer({size:16,usage:GPUBufferUsage.UNIFORM|GPUBufferUsage.COPY_DST});
  device.queue.writeBuffer(finalParams,0,new Float32Array([width,height,0,0]));
  const finalGroup=device.createBindGroup({layout:compositePipeline.getBindGroupLayout(0),entries:[
    {binding:0,resource:near.createView()}, {binding:1,resource:far.createView()},
    {binding:2,resource:inner.createView()}, {binding:3,resource:outer.createView()},
    {binding:4,resource:blur.createView()}, {binding:5,resource:sampler},
    {binding:6,resource:{buffer:finalParams}}
  ]});
  let disposed=false;
  function draw(){
    if(disposed)return;
    const encoder=device.createCommandEncoder();
    for(const pass of stageInputs){
      const renderPass=encoder.beginRenderPass({colorAttachments:[{
        view:pass.to.createView(),loadOp:"clear",storeOp:"store"
      }]});
      renderPass.setPipeline(blurPipeline);
      renderPass.setBindGroup(0,pass.group);
      renderPass.draw(3);renderPass.end();
    }
    const renderPass=encoder.beginRenderPass({colorAttachments:[{
      view:context.getCurrentTexture().createView(),loadOp:"clear",storeOp:"store"
    }]});
    renderPass.setPipeline(compositePipeline);
    renderPass.setBindGroup(0,finalGroup);
    renderPass.draw(3);renderPass.end();
    device.queue.submit([encoder.finish()]);
  }
  draw();
  async function benchmark(samples=80){
    const durations=[];
    for(let i=0;i<samples;i++){
      const start=performance.now();
      draw();
      await device.queue.onSubmittedWorkDone();
      durations.push(performance.now()-start);
    }
    const sorted=durations.toSorted((a,b)=>a-b);
    return {samples,medianMs:sorted[Math.floor(samples/2)],
      p95Ms:sorted[Math.floor(.95*(samples-1))],maxMs:sorted.at(-1),
      totalMs:durations.reduce((a,b)=>a+b,0)};
  }
  return {draw,benchmark,device,adapter,source:field,
    dispose(){if(disposed)return;disposed=true;for(const t of textures)t.destroy();
      for(const p of stageInputs)p.buffer.destroy();finalParams.destroy();device.destroy();}};
}

export const GPU_LAB_SHADER_SOURCES=Object.freeze({blur:blurShader,composite:glassShader});
